import inspect
import ledger

_MISSING = object()

_ACCOUNT_NAMES = {"acct", "account", "account_id", "account_name", "account_no"}
_AMOUNT_NAMES = {"wire", "amount", "amt", "value"}
_MEMO_NAMES = {"memo", "description", "note", "comment"}


def _value_for(name, position, acct, wire):
    key = name.lower().lstrip("_")

    if key in _MEMO_NAMES or "memo" in key:
        return "wire"
    if key in _AMOUNT_NAMES or "amount" in key or "wire" in key:
        return wire
    if key in _ACCOUNT_NAMES or "account" in key:
        return acct

    if position == 0:
        return acct
    if position == 1:
        return wire
    if position == 2:
        return "wire"

    return _MISSING


def store(acct, wire):
    write = ledger.write

    try:
        sig = inspect.signature(write)
    except (TypeError, ValueError):
        return write(acct, wire, "wire")

    params = [
        p for p in sig.parameters.values()
        if p.kind not in (inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD)
    ]

    if not params:
        return write(acct, wire, "wire")

    args = []
    kwargs = {}

    for pos, param in enumerate(params):
        value = _value_for(param.name, pos, acct, wire)
        if value is _MISSING:
            if param.default is not inspect.Parameter.empty:
                continue
            return write(acct, wire, "wire")

        if param.kind in (inspect.Parameter.POSITIONAL_ONLY, inspect.Parameter.POSITIONAL_OR_KEYWORD):
            args.append(value)
        elif param.kind is inspect.Parameter.KEYWORD_ONLY:
            kwargs[param.name] = value

    return write(*args, **kwargs)

